type Page='dashboard'|'agenda'|'financeiro'|'estudos'|'academia'|'alimentacao'|'negocios'|'projetos'|'habitos'|'configuracoes';
const NAV:{id:Page;label:string;icon:typeof Home;group:string}[]=[
 {id:'dashboard',label:'Visão geral',icon:LayoutGrid,group:'PRINCIPAL'},
 {id:'agenda',label:'Agenda e tarefas',icon:CalendarDays,group:'PRINCIPAL'},
 {id:'financeiro',label:'Financeiro',icon:Wallet,group:'GESTÃO'},
 {id:'estudos',label:'Estudos',icon:GraduationCap,group:'GESTÃO'},
 {id:'academia',label:'Academia e saúde',icon:Dumbbell,group:'GESTÃO'},
 {id:'alimentacao',label:'Alimentação e nutrição',icon:HeartPulse,group:'GESTÃO'},
 {id:'negocios',label:'Negócios',icon:BriefcaseBusiness,group:'GESTÃO'},
 {id:'projetos',label:'Projetos e metas',icon:FolderKanban,group:'GESTÃO'},
 {id:'habitos',label:'Hábitos',icon:Target,group:'PESSOAL'},
 {id:'configuracoes',label:'Configurações',icon:Settings2,group:'SISTEMA'}
];
const linked:Partial<Record<Collection,Page>>={transactions:'financeiro',tasks:'agenda',events:'agenda',subjects:'estudos',studies:'estudos',workouts:'academia',clients:'negocios',deals:'negocios',businesses:'negocios',projects:'projetos',goals:'projetos',habits:'habitos'};
const i=(n:unknown)=>Number(n)||0;
const sum=(values:Entry[],predicate?:(x:Entry)=>boolean,field='amount')=>values.filter(x=>!predicate||predicate(x)).reduce((total,x)=>total+i(x[field]),0);
const dayOfWeek=(s:string)=>new Date(s+'T12:00:00').toLocaleDateString('pt-BR',{weekday:'long'});
const longDate=(s:string)=>new Date(s+'T12:00:00').toLocaleDateString('pt-BR',{day:'numeric',month:'long',year:'numeric'});
const initials=(value:string)=>value.trim().split(/\s+/).slice(0,2).map(x=>x[0]?.toUpperCase()).join('')||'EU';
const cx=(...a:(string|false|undefined)[])=>a.filter(Boolean).join(' ');
const formatMinutes=(m:number)=>m>=60?`${Math.floor(m/60)}h ${String(m%60).padStart(2,'0')}m`:`${m} min`;
const currentMonth=()=>today().slice(0,7);
function IconTile({children,variant='neutral'}:{children:ReactNode;variant?:string}){return <span className={'icon-tile '+variant}>{children}</span>}
function Badge({children,tone='muted'}:{children:ReactNode;tone?:string}){return <span className={'badge '+tone}>{children}</span>}
function Progress({value,color='ink'}:{value:number;color?:string}){return <div className="progress-track"><span className={'progress-fill '+color} style={{width:`${Math.max(0,Math.min(100,value))}%`}}/></div>}
function Empty({icon:Icon,title,body,onAdd,cta='Adicionar novo'}:{icon:typeof Home;title:string;body:string;onAdd?:()=>void;cta?:string}){return <div className="empty"><span className="empty-icon"><Icon size={25} strokeWidth={1.6}/></span><strong>{title}</strong><span>{body}</span>{onAdd&&<button className="btn light" onClick={onAdd}><Plus size={15}/>{cta}</button>}</div>}
function Panel({title,subtitle,action,children,className=''}:{title:string;subtitle?:string;action?:ReactNode;children:ReactNode;className?:string}){return <section className={'panel '+className}><header className="panel-head"><div><h3>{title}</h3>{subtitle&&<p>{subtitle}</p>}</div>{action}</header>{children}</section>}
function SectionHeading({eyebrow,title,description,actions}:{eyebrow?:string;title:string;description?:string;actions?:ReactNode}){return <header className="page-heading"><div>{eyebrow&&<div className="eyebrow">{eyebrow}</div>}<h1>{title}</h1>{description&&<p>{description}</p>}</div><div className="heading-actions">{actions}</div></header>}
function FieldLine({label,value,icon:Icon}:{label:string;value:string;icon:typeof Home}){return <span className="field-line"><Icon size={14}/>{label}<strong>{value}</strong></span>}
function Table({columns,rows}:{columns:{title:string;render:(x:Entry)=>ReactNode;className?:string}[];rows:Entry[]}){return <div className="table-wrap" tabIndex={0} aria-label="Tabela de registros"><table><thead><tr>{columns.map((c,j)=><th key={j} className={c.className}>{c.title}</th>)}</tr></thead><tbody>{rows.map(r=><tr key={r.id}>{columns.map((c,j)=><td key={j} data-label={c.title} className={c.className}>{c.render(r)}</td>)}</tr>)}</tbody></table></div>}
function MenuActions({onEdit,onDelete}:{onEdit:()=>void;onDelete:()=>void}){return <div className="row-actions"><button className="icon-button" title="Editar" onClick={onEdit}><Edit3 size={15}/></button><button className="icon-button danger" title="Excluir" onClick={onDelete}><Trash2 size={15}/></button></div>}

export default function App(){
 const [store,setStore]=useState<Store>(loadStore);
 const topbarRef=useRef<HTMLElement>(null);
 useEffect(()=>{
  const bar=topbarRef.current;if(!bar)return;
  const update=()=>bar.parentElement?.style.setProperty('--app-topbar-height',`${bar.getBoundingClientRect().height}px`);
  update();const observer=new ResizeObserver(update);observer.observe(bar);
  return()=>observer.disconnect();
 },[]);
 const enabled=enabledModules(store.preferences.enabledModules);
 const enabledKey=enabled.join(',');
 const can=(id:string)=>pageEnabled(id,enabled);
 const visibleNav=NAV.filter(n=>can(n.id));
 const [requestedPage,navigate]=usePageNavigation<Page>(NAV.map(n=>n.id),'dashboard');
 const page=can(requestedPage)?requestedPage:'dashboard';
 const setPage=(next:Page)=>navigate(can(next)?next:'dashboard');
 useEffect(()=>{if(!pageEnabled(requestedPage,enabled)){history.replaceState({},'','#dashboard');navigate('dashboard')}},[requestedPage,enabledKey,navigate]);
 const [modal,setModal]=useState<{kind:Collection;item?:Entry}|null>(null);
 const [form,setForm]=useState<Record<string,string>>({});
 const [businessUpload,setBusinessUpload]=useState(false);
 useEffect(()=>{setBusinessUpload(false)},[modal]);
 const [searchOpen,setSearchOpen]=useState(false),[search,setSearch]=useState('');
 const {navOpen,setNavOpen,drawer}=useMobileNavigation();
 const [toast,setToast]=useState('');
 const [isOnline,setIsOnline]=useState(()=>navigator.onLine);
 const [backendReachable,setBackendReachable]=useState(true);
 const [syncPending,setSyncPending]=useState(false);
 const [storageWarning,setStorageWarning]=useState(false);
 useEffect(()=>{
  let alive=true;
  const check=async()=>{
   if(!navigator.onLine){if(alive)setBackendReachable(false);return}
   const controller=new AbortController(),timeout=window.setTimeout(()=>controller.abort(),6500);
   try{const response=await fetch('/api/health',{cache:'no-store',credentials:'same-origin',signal:controller.signal});
    if(alive)setBackendReachable(response.ok&&(await response.json()).ok===true)}
   catch{if(alive)setBackendReachable(false)}finally{window.clearTimeout(timeout)}
  };
  void check();const timer=window.setInterval(()=>void check(),30000);
  const onActive=()=>{if(document.visibilityState==='visible')void check()};
  window.addEventListener('online',onActive);document.addEventListener('visibilitychange',onActive);
  return()=>{alive=false;window.clearInterval(timer);window.removeEventListener('online',onActive);document.removeEventListener('visibilitychange',onActive)};
 },[]);
 useEffect(()=>{
  const update=()=>{setIsOnline(navigator.onLine);setSyncPending(hasPendingChanges())};
  const poll=window.setInterval(update,1200);update();
  window.addEventListener('online',update);window.addEventListener('offline',update);
  const beforeLeave=(event:BeforeUnloadEvent)=>{if(hasPendingChanges()){event.preventDefault();event.returnValue=''}};
  window.addEventListener('beforeunload',beforeLeave);
  return()=>{window.clearInterval(poll);window.removeEventListener('online',update);window.removeEventListener('offline',update);window.removeEventListener('beforeunload',beforeLeave)};
 },[]);
 const [demoBusy,setDemoBusy]=useState(false);
 const changeDemo=async(load:boolean)=>{
  if(demoBusy)return;
  const message=load?'Carregar uma demonstração completa em todos os módulos? Isso substitui os dados atuais. Exporte um backup antes de continuar.':'Limpar todos os dados deste espaço de demonstração? Alterações feitas nos exemplos também serão removidas.';
  if(!window.confirm(message))return;
  setDemoBusy(true);
  try{
   const next=isCloud()?await runErpCommand(load?'demo.load':'demo.clear',store.preferences.workspaceId,{confirm:true}):load?demoStore(store.preferences):emptyDemoState(store.preferences);
   setStore(next);setToast(load?'Demonstração completa ativada em todos os módulos.':'Demonstração removida.');navigate('dashboard');
  }catch(error){setToast(error instanceof Error?error.message:'Não foi possível atualizar a demonstração. Tente novamente.')}
  finally{setDemoBusy(false)}
 };
 const {account,openAccount,openPlans,logout}=useAccount();
 const displayName=account?.displayName||account?.fullName||store.preferences.name||'Minha conta';
 const [collapsed,setCollapsed]=useState<string[]>([]);
 const [calendarMonth,setCalendarMonth]=useState(currentMonth());
 const [selectedDate,setSelectedDate]=useState(today());
 const [period,setPeriod]=useState('Este mês');
 const [financialFilter,setFinancialFilter]=useState('Todos');
 const [tab,setTab]=useState('Todos');
 const importRef=useRef<HTMLInputElement>(null);
 const activeWorkspace=store.preferences.workspaceId;
 useEffect(()=>{if(activeWorkspace!=='pessoal'&&!store.collections.businesses.some(b=>b.id===activeWorkspace)){setStore(s=>({...s,preferences:{...s.preferences,workspaceId:'pessoal'}}));setToast('O espaço anterior não está mais disponível. Retornamos ao espaço pessoal.')}},[activeWorkspace,store.collections.businesses]);
 const workspaceList=[{id:'pessoal',title:'Meu espaço pessoal'},...store.collections.businesses.map(x=>({id:x.id,title:x.title}))];
 const items=(key:Collection)=>key==='businesses'?store.collections[key]:store.collections[key].filter(x=>(x.workspaceId||'pessoal')===activeWorkspace);
 const all=(key:Collection)=>store.collections[key];
 const editPrefs=(changes:Partial<Store['preferences']>)=>setStore(s=>({...s,preferences:{...s.preferences,...changes}}));
 useEffect(()=>{
  try{if(isCloud())sessionStorage.setItem(STORAGE_KEY,JSON.stringify(store));else localStorage.setItem(STORAGE_KEY,JSON.stringify(store));setStorageWarning(false)}
  catch{setStorageWarning(true)}
  if(isCloud())enqueueCloud(store);
 },[store]);
 useEffect(()=>{document.documentElement.setAttribute('data-theme',store.preferences.theme);try{localStorage.setItem('eixo-theme',store.preferences.theme)}catch{}document.querySelector('meta[name="theme-color"]')?.setAttribute('content',store.preferences.theme==='dark'?'#10171f':'#f3f5f8')},[store.preferences.theme]);
 useEffect(()=>{if(!toast)return;const t=setTimeout(()=>setToast(''),3200);return()=>clearTimeout(t)},[toast]);
 useEffect(()=>{function keyboard(e:KeyboardEvent){if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();setSearchOpen(v=>!v)}if(e.key==='Escape'){setSearchOpen(false);setModal(null)}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='j'){e.preventDefault();if(can('agenda'))openCreate('tasks')}}window.addEventListener('keydown',keyboard);return()=>window.removeEventListener('keydown',keyboard)},[enabledKey]);
 const openCreate=(kind:Collection)=>{setForm(initialValues(kind));setModal({kind})};
 const openEdit=(kind:Collection,item:Entry)=>{setForm(Object.fromEntries(Object.entries(item).filter(([k,v])=>k!=='id'&&k!=='createdAt'&&k!=='workspaceId').map(([k,v])=>[k,String(v??'')])));setModal({kind,item})};
 const save=(e:FormEvent)=>{e.preventDefault();if(!modal)return;const kind=modal.kind;const title=form.title?.trim();if(!title){setToast('Informe o nome ou descrição.');return}if(config[kind].fields.some(f=>f.required&&f.key!=='title'&&!String(form[f.key]||'').trim())){setToast('Preencha os campos obrigatórios.');return}
 if(kind==='transactions'&&(!Number.isFinite(Number(form.amount))||Number(form.amount)<=0||Number(form.amount)>100000000)){setToast('O valor do lançamento deve ser maior que zero e válido.');return}
 const record:Entry={...modal.item,id:modal.item?.id||uid(),createdAt:modal.item?.createdAt||new Date().toISOString(),workspaceId:modal.item?.workspaceId||activeWorkspace,title};
 for(const field of config[kind].fields)if(field.key!=='title'){let v:string|number=form[field.key]||'';if(field.kind==='number')v=v===''?'':Number(v);record[field.key]=v}
 if(kind==='businesses')record.logoId=form.logoId||'';
 setStore(s=>({...s,collections:{...s.collections,[kind]:modal.item?s.collections[kind].map(x=>x.id===modal.item?.id?record:x):[record,...s.collections[kind]]}}));setModal(null);setToast(modal.item?'Registro atualizado.':'Registro adicionado.');};
 const remove=(kind:Collection,item:Entry)=>{if(!window.confirm(`Excluir "${item.title}"? Esta ação não pode ser desfeita.`))return;setStore(s=>({...s,collections:{...s.collections,[kind]:s.collections[kind].filter(x=>x.id!==item.id)}}));setToast('Registro excluído.')};
 const tx=items('transactions'), task=items('tasks'), event=items('events'), studies=items('studies'), workouts=items('workouts');
 const month=currentMonth(), monthly=tx.filter(x=>String(x.date||'').startsWith(month));
 const income=sum(monthly,x=>x.type==='Receita'),expenses=sum(monthly,x=>x.type!=='Receita');
 const totalBalance=sum(tx,x=>x.type==='Receita')-sum(tx,x=>x.type!=='Receita');
 const undone=task.filter(x=>x.status!=='Concluído'),doneCount=task.filter(x=>x.status==='Concluído').length;
 const trainingTime={now:new Date().toISOString(),timeZone:resolveTimeZone(account?.timezone)};
 const trainingToday=dateInZone(trainingTime.now,trainingTime.timeZone)!;
 const weekStart=shiftDay(trainingToday,-((new Date(trainingToday+'T12:00:00Z').getUTCDay()+6)%7));
 const thisWeekTraining=(store.training?.sessions||[]).filter(s=>s.workspaceId===activeWorkspace).filter(s=>{const day=completedSessionDate(s,trainingTime);return day&&day>=weekStart&&day<=trainingToday}).length;
 const studiedMinutes=sum(studies,undefined,'duration');
 const actionNotices=getActionCenter({tasks:task,events:event,erp:store.erp,transactions:tx,budgets:store.budgets,workspaceId:activeWorkspace,today:today()}).filter(notice=>can(notice.page));
 const futureEvents=[...event].filter(x=>String(x.date||'')>=today()).sort((a,b)=>String(a.date)+String(a.time||'')>String(b.date)+String(b.time||'')?1:-1);
 const monthFlow=useMemo(()=>Array.from({length:6},(_,idx)=>{const d=new Date();d.setDate(1);d.setMonth(d.getMonth()-5+idx);const m=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;const subset=tx.filter(x=>String(x.date||'').startsWith(m));return {month:d.toLocaleDateString('pt-BR',{month:'short'}).replace('.',''),Receitas:sum(subset,x=>x.type==='Receita'),Despesas:sum(subset,x=>x.type!=='Receita')}}),[store,activeWorkspace]);
 const commonActions=(key:Collection)=> <button className="btn primary" onClick={()=>openCreate(key)}><Plus size={17}/>Adicionar {config[key].singular}</button>;
 const editActions=(key:Collection,x:Entry)=><MenuActions onEdit={()=>openEdit(key,x)} onDelete={()=>remove(key,x)}/>;
 const empty=(key:Collection,Icon:typeof Home,title?:string)=> <Empty icon={Icon} title={title||'Nenhum registro ainda'} body="Seus registros aparecerão aqui assim que você adicionar o primeiro." onAdd={()=>openCreate(key)} cta={`Adicionar ${config[key].singular}`}/>;
 const pageTitle=NAV.find(x=>x.id===page)?.label||'Visão geral';
 const exportData=()=>{const blob=new Blob([JSON.stringify(store,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`eixo-backup-${today()}.json`;a.click();window.setTimeout(()=>URL.revokeObjectURL(url),3000);setToast('Backup exportado.')};
 const readImport=async(e:ChangeEvent<HTMLInputElement>)=>{const file=e.target.files?.[0];if(!file)return;try{if(file.size>10_000_000)throw Error('O arquivo excede 10 MB.');const next=JSON.parse(await file.text());if(!validImport(next))throw Error('Arquivo de backup inválido.');if(!window.confirm('Substituir todos os dados atuais pelos dados deste backup?'))return;if(isCloud()&&JSON.stringify(parseERP(next.erp))!==JSON.stringify(parseERP(store.erp))){throw Error('Por segurança, o histórico de estoque, vendas e pagamentos não pode ser substituído diretamente por um arquivo. Seu backup foi preservado. A restauração do ERP exige um procedimento autenticado de migração.')}const state=emptyStore();for(const g of groups)state.collections[g]=next.collections[g];setStore({...state,...next,collections:state.collections,preferences:{...state.preferences,...next.preferences},budgets:normalizeBudgets(next.budgets),focusSessions:normalizeFocusSessions(next.focusSessions),erp:parseERP(next.erp),training:parseTraining(next.training),nutrition:parseNutrition(next.nutrition),study:parseStudy(next.study)});setToast('Backup restaurado.')}catch(err){setToast(err instanceof Error?err.message:'Erro ao importar arquivo.')}finally{e.target.value=''}};
 const mainSearch=normalizeSearch(search);
 const results=searchWorkspaceRecords(store.collections,groups.filter(g=>can(linked[g]||'dashboard')),activeWorkspace,mainSearch);
 const quickActions:[string,Page,Collection|null][]=[
  ['Visão geral','dashboard',null],['Financeiro','financeiro',null],['Agenda e tarefas','agenda',null],
  ['Estudos','estudos',null],['Academia e saúde','academia',null],['Alimentação','alimentacao',null],
  ['Negócios e PDV','negocios',null],['Projetos','projetos',null],['Hábitos','habitos',null],
  ['Configurações','configuracoes',null],['Nova tarefa','agenda','tasks'],
  ['Novo compromisso','agenda','events'],['Nova receita ou despesa','financeiro','transactions'],
  ['Novo cliente','negocios','clients'],['Nova empresa','negocios','businesses'],
  ['Novo projeto','projetos','projects'],['Nova meta','projetos','goals']
 ];
 const paletteActions=quickActions.filter(([,target])=>can(target)).filter(([label])=>!mainSearch||normalizeSearch(label).includes(mainSearch)).slice(0,7);
 const runPaletteAction=(target:Page,kind:Collection|null)=>{setSearchOpen(false);setSearch('');setPage(target);if(kind)openCreate(kind)};
 const workspaceTitle=workspaceList.find(w=>w.id===activeWorkspace)?.title||'Meu espaço pessoal';
 return <div className="shell">
  {navOpen&&<button className="mobile-overlay" onClick={()=>setNavOpen(false)} aria-label="Fechar menu"/>}
  <aside ref={drawer} id="main-navigation" aria-label="Menu principal" className={cx('sidebar',navOpen&&'open')}>
   <div className="brand"><Brand/><button className="icon-button nav-close" aria-label="Fechar menu" onClick={()=>setNavOpen(false)}><X size={20}/></button></div>
   <div className="workspace"><Avatar name={workspaceTitle} src={store.collections.businesses.find(b=>b.id===activeWorkspace)?.logoId?'/api/media/'+store.collections.businesses.find(b=>b.id===activeWorkspace)?.logoId:null}/><div><span className="workspace-hint">ESPAÇO ATIVO</span><select aria-label="Selecionar espaço" value={activeWorkspace} onChange={e=>editPrefs({workspaceId:e.target.value})}>{workspaceList.map(w=><option key={w.id} value={w.id}>{w.title}</option>)}</select></div><ChevronDown size={14} className="workspace-arrow"/></div>
   <nav className="navigation">{['PRINCIPAL','GESTÃO','PESSOAL','SISTEMA'].filter(group=>visibleNav.some(n=>n.group===group)).map(group=><div className="nav-group" key={group}><button className="nav-label" aria-expanded={!collapsed.includes(group)} onClick={()=>setCollapsed(v=>v.includes(group)?v.filter(x=>x!==group):[...v,group])}>{group}<ChevronDown size={13}/></button>{!collapsed.includes(group)&&visibleNav.filter(n=>n.group===group).map(n=><button key={n.id} onClick={()=>{setPage(n.id);setNavOpen(false);setTab('Todos')}} aria-current={page===n.id?'page':undefined} className={cx('nav-link',page===n.id&&'active')}><n.icon size={18} strokeWidth={1.9}/><span>{n.label}</span>{page===n.id&&<i/>}</button>)}</div>)}</nav>
   <div className="sidebar-bottom"><button className="shortcut" onClick={()=>{setNavOpen(false);setSearchOpen(true)}}><Search size={16}/><span>Busca rápida</span><kbd>Ctrl K</kbd></button><button className="sidebar-profile" onClick={()=>{setNavOpen(false);openAccount()}}><Avatar name={displayName} src={account?.avatarUrl}/><span className="profile-copy"><strong>{displayName}</strong><small>{account?.email||'Conta local'}</small></span><ChevronRight size={16}/></button><div className="sidebar-account-actions"><button onClick={()=>{setNavOpen(false);openPlans()}}><CreditCard size={15}/> Assinatura</button><button onClick={()=>{setNavOpen(false);logout()}}>Sair <ArrowRight size={15}/></button></div></div>
  </aside>
  <div className="main-wrap">
   <header ref={topbarRef} className="topbar"><div className="top-left"><button className="icon-button mobile-menu" onClick={()=>setNavOpen(true)} aria-label="Abrir menu" aria-controls="main-navigation" aria-expanded={navOpen}><Menu size={21}/></button><span className="crumb-root">{workspaceTitle}</span><ChevronRight size={14} className="crumb-divider"/><span className="crumb-current">{pageTitle}</span></div><div className="top-right"><span className="saved-indicator" data-status={storageWarning?'error':!isOnline||!backendReachable?'offline':syncPending?'pending':'saved'} title={storageWarning?'Falha ao salvar no armazenamento do navegador. Exporte um backup.':!isOnline?'Sem acesso à internet.':!backendReachable?'O servidor EIXO não respondeu à verificação de saúde.':syncPending?'Alterações aguardando sincronização.':'Nenhuma alteração pendente.'}><span/>{storageWarning?'Falha no salvamento':!isOnline?'Sem conexão':!backendReachable?'Servidor indisponível':syncPending?'Salvando alterações…':'Dados sincronizados'}</span><button className="icon-button" onClick={()=>setSearchOpen(true)} title="Pesquisar"><Search size={19}/></button><button className="icon-button" onClick={()=>editPrefs({theme:store.preferences.theme==='light'?'dark':'light'})} title="Alternar tema">{store.preferences.theme==='light'?<Moon size={19}/>:<Sun size={19}/>}</button><button className="profile-circle" aria-label="Minha conta" onClick={openAccount}><Avatar name={displayName} src={account?.avatarUrl}/></button></div></header>
   <main className="content" key={page}>
   {store.demo&&<div className="demo-banner"><Sparkles size={16}/> Demonstração completa ativa. Explore todos os módulos no espaço Horizonte • Demonstração. Os dados são fictícios. <button disabled={demoBusy} onClick={()=>void changeDemo(false)}>{demoBusy?'Aguarde…':'Limpar demonstração'} <ArrowRight size={14}/></button></div>}
   {page==='dashboard'&&<>
    <SectionHeading eyebrow="SEU PAINEL" title={`Olá, ${displayName.split(' ')[0]}.`} description={`Hoje é ${dayOfWeek(today())}, ${longDate(today())}. Tudo o que importa, em um só lugar.`} actions={<>{can('agenda')&&<><button className="btn light" onClick={()=>setPage('agenda')}><CalendarDays size={16}/> Abrir agenda</button><button className="btn primary" onClick={()=>openCreate('tasks')}><Plus size={17}/> Nova tarefa</button></>}<button className="btn light" onClick={()=>setPage('configuracoes')}><SlidersHorizontal size={16}/> Meus módulos</button></>}/>
    {can('agenda')&&<Suspense fallback={<div className="module-skeleton" role="status">Preparando central Meu Dia...</div>}><DayCommandCenter store={store} setStore={setStore} workspaceId={activeWorkspace} accountKey={account?.email||'local'} tasks={task} events={event} onOpenTask={item=>openEdit('tasks',item)} onOpenEvent={item=>openEdit('events',item)} onCreateTask={date=>{setForm({...initialValues('tasks'),dueDate:date});setModal({kind:'tasks'})}} onCreateEvent={date=>{setForm({...initialValues('events'),date});setModal({kind:'events'})}} onOpenAgenda={()=>setPage('agenda')}/></Suspense>}
    <div className="module-launchers">{MODULES.filter(m=>enabled.includes(m.id)).map(m=>{const Icon=moduleIcons[m.id];return <button key={m.id} onClick={()=>setPage(m.id)}><span className="module-symbol"><Icon size={20}/></span><span><strong>{m.title}</strong><small>{m.description}</small></span><ArrowUpRight size={16}/></button>})}</div>
    {!enabled.length&&<Panel title="Um espaço para o seu momento" subtitle="Comece quando quiser"><Empty icon={LayoutGrid} title="O que você quer organizar?" body="Escolha seus módulos para montar um painel com o que importa para você." onAdd={()=>setPage('configuracoes')} cta="Escolher meus módulos"/></Panel>}
    <div className="metrics modular-metrics">
      {can('financeiro')&&<article className="metric featured" data-tone={balanceTone(totalBalance)}><div className="metric-title">Saldo total <Wallet size={19}/></div><div className="metric-value">{formatMoney(totalBalance)}</div><div className="metric-foot"><span className="metric-pill"><ArrowUpRight size={13}/> Entradas: {formatMoney(income)}</span><span className="indicator-label">{balanceLabel(totalBalance)}</span></div><div className="metric-pattern"/></article>}
      {can('agenda')&&<article className="metric" data-tone={undone.some(x=>x.dueDate&&String(x.dueDate)<today())?'negative':undone.length?'warning':'positive'}><div className="metric-title">Tarefas pendentes <CheckCheck size={19}/></div><div className="metric-value">{undone.length}<span className="metric-unit">tarefas</span></div><div className="metric-foot"><span className="muted">{doneCount} concluídas no total</span></div></article>}
      {can('academia')&&<article className="metric" data-tone={thisWeekTraining>=store.preferences.weeklyTrainingGoal?'positive':'info'}><div className="metric-title">Treinos nesta semana <Dumbbell size={19}/></div><div className="metric-value">{thisWeekTraining}<span className="metric-unit">/ {store.preferences.weeklyTrainingGoal}</span></div><div className="metric-foot metric-progress"><Progress value={100*thisWeekTraining/Math.max(1,store.preferences.weeklyTrainingGoal)} color="blue"/></div></article>}
      {can('estudos')&&<article className="metric" data-tone={'info'}><div className="metric-title">Tempo de estudo <BookOpen size={19}/></div><div className="metric-value">{formatMinutes(studiedMinutes)}</div><div className="metric-foot"><span className="muted">total registrado</span></div></article>}
    </div>
     {(can('agenda')||can('negocios'))&&<Panel title="Central de atenção" subtitle="O que precisa da sua atenção agora" className="eixo-attention-panel"><div className="eixo-attention-grid">{actionNotices.length?actionNotices.map(notice=><button key={notice.id} className="eixo-attention-item" data-tone={notice.tone} onClick={()=>setPage(notice.page)}><span className="eixo-attention-count">{notice.count}</span><span><strong>{notice.title}</strong><small>{notice.description}</small></span><ArrowUpRight size={16}/></button>):<div className="eixo-attention-clear"><CheckCheck size={19}/><span>Tudo em dia neste espaço. Continue acompanhando suas atividades.</span></div>}</div></Panel>}
     {can('academia')&&<Suspense fallback={<div className="module-skeleton" role="status">Preparando mapa muscular...</div>}><TrainingStudio key={activeWorkspace} store={store} setStore={setStore} workspaceId={activeWorkspace} legacy={workouts} compact onOpen={()=>setPage('academia')}/></Suspense>}
    <div className="dashboard-grid">{can('financeiro')&&<Panel title="Fluxo financeiro" subtitle="Receitas e despesas dos últimos 6 meses" action={<button className="text-action" onClick={()=>setPage('financeiro')}>Ver financeiro <ArrowRight size={15}/></button>}><div className="chart-space">{tx.length?<ResponsiveContainer width="100%" height="100%"><BarChart data={monthFlow} barGap={6}><CartesianGrid vertical={false} stroke="var(--line)" strokeDasharray="3 4"/><XAxis dataKey="month" tickLine={false} axisLine={false} tick={{fill:'var(--text-muted)',fontSize:12}}/><YAxis hide/><Tooltip formatter={(v)=>formatMoney(Number(v))} contentStyle={{border:'1px solid var(--border)',borderRadius:12,background:'var(--surface)',color:'var(--text)',fontSize:12}}/><Bar dataKey="Receitas" fill="var(--success)" radius={[4,4,0,0]} maxBarSize={21}/><Bar dataKey="Despesas" fill="var(--danger)" radius={[4,4,0,0]} maxBarSize={21}/></BarChart></ResponsiveContainer>:<Empty icon={BarChart3} title="Seu histórico financeiro" body="Registre receitas e despesas para visualizar a evolução." onAdd={()=>openCreate('transactions')} cta="Adicionar lançamento"/>}</div><div className="chart-legend"><span><i className="legend-dot dark"/>Receitas</span><span><i className="legend-dot pale"/>Despesas</span></div></Panel>}
     {can('agenda')&&<Panel title="Próximos compromissos" subtitle="Sua agenda nos próximos dias" action={<button className="text-action" onClick={()=>setPage('agenda')}>Ver agenda <ArrowRight size={15}/></button>}><div className="dashboard-list">{futureEvents.length?futureEvents.slice(0,5).map(x=><button className="timeline-item" key={x.id} onClick={()=>openEdit('events',x)}><div className="timeline-date"><b>{String(x.date).slice(8,10)}</b><small>{new Date(String(x.date)+'T12:00:00').toLocaleDateString('pt-BR',{month:'short'}).replace('.','')}</small></div><div className="timeline-copy"><strong>{x.title}</strong><span>{x.category||'Compromisso'} {x.time?'· '+x.time:''}</span></div><ArrowUpRight size={16}/></button>):<Empty icon={CalendarDays} title="Agenda livre" body="Adicione compromissos para organizar sua rotina." onAdd={()=>openCreate('events')} cta="Novo compromisso"/>}</div></Panel>}
    </div>
    <div className="dashboard-grid bottom-grid">{can('agenda')&&<Panel title="Suas prioridades" subtitle="Tarefas que precisam de atenção" action={<button className="text-action" onClick={()=>setPage('agenda')}>Todas as tarefas <ArrowRight size={15}/></button>}><div className="task-stack">{undone.length?undone.slice(0,5).map(x=><button className="task-line" key={x.id} onClick={()=>openEdit('tasks',x)}><span className="task-box"/><span className="task-desc"><strong>{x.title}</strong><small>{x.category||'Pessoal'} {x.dueDate?'· '+fmtDate(String(x.dueDate)):''}</small></span><Badge tone={x.priority==='Alta'?'rose':x.priority==='Média'?'amber':'muted'}>{x.priority||'Normal'}</Badge></button>):<Empty icon={CheckCheck} title="Tudo em dia" body="Nenhuma tarefa pendente por enquanto." onAdd={()=>openCreate('tasks')} cta="Criar tarefa"/>}</div></Panel>}
     {can('projetos')&&<Panel title="Metas em andamento" subtitle="O que você está construindo" action={<button className="text-action" onClick={()=>setPage('projetos')}>Ver metas <ArrowRight size={15}/></button>}><div className="goal-stack">{items('goals').length?items('goals').slice(0,4).map(x=><button key={x.id} className="goal-line" onClick={()=>openEdit('goals',x)}><div className="goal-head"><strong>{x.title}</strong><span>{Math.min(100,Math.round(i(x.current)/Math.max(i(x.target),1)*100))}%</span></div><Progress value={i(x.current)/Math.max(1,i(x.target))*100} color="blue"/><small>{i(x.current).toLocaleString('pt-BR')} de {i(x.target).toLocaleString('pt-BR')} {x.unit||''}</small></button>):<Empty icon={Target} title="Defina seu próximo objetivo" body="Acompanhe pequenas evoluções rumo às suas metas." onAdd={()=>openCreate('goals')} cta="Criar meta"/>}</div></Panel>}</div>
   </>}
   {page==='financeiro'&&<>
    <SectionHeading eyebrow="CONTROLE FINANCEIRO" title="Financeiro" description="Clareza sobre cada movimento do seu dinheiro." actions={<><button className="btn light" onClick={exportData}><Download size={16}/> Exportar dados</button>{commonActions('transactions')}</>}/>
    <div className="metrics three"><article className="metric" data-tone={balanceTone(totalBalance)}><div className="metric-title">Saldo acumulado <Wallet size={18}/></div><div className="metric-value">{formatMoney(totalBalance)}</div><div className="metric-foot muted"><span className="indicator-label">{balanceLabel(totalBalance)}</span> · Entradas menos saídas</div></article><article className="metric" data-tone={income>0?'positive':'neutral'}><div className="metric-title">Entradas no mês <TrendingUp size={18}/></div><div className="metric-value">{formatMoney(income)}</div><div className="metric-foot green-text">Receitas · {new Date().toLocaleDateString('pt-BR',{month:'long'})}</div></article><article className="metric" data-tone={expenses>0?'negative':'neutral'}><div className="metric-title">Saídas no mês <TrendingDown size={18}/></div><div className="metric-value">{formatMoney(expenses)}</div><div className="metric-foot muted">Despesas · {new Date().toLocaleDateString('pt-BR',{month:'long'})}</div></article></div>
    <div className="indicator-legend" aria-label="Legenda financeira"><span data-tone="positive"><i/> Entradas · dinheiro recebido</span><span data-tone="negative"><i/> Saídas · dinheiro gasto</span></div>
    <Suspense fallback={<div className="module-skeleton" role="status">Preparando planejamento financeiro...</div>}><FinancialPlanner store={store} setStore={setStore} workspaceId={activeWorkspace} entries={tx} onAddTransaction={()=>openCreate('transactions')}/></Suspense>
    <div className="finance-layout"><Panel title="Visão dos últimos meses" subtitle="Acompanhe o comportamento das suas finanças"><div className="chart-space tall">{tx.length?<ResponsiveContainer width="100%" height="100%"><AreaChart data={monthFlow}><defs><linearGradient id="incomeGradient" x1="0" x2="0" y1="0" y2="1"><stop offset="5%" stopColor="var(--success)" stopOpacity={.2}/><stop offset="95%" stopColor="var(--success)" stopOpacity={0}/></linearGradient></defs><CartesianGrid stroke="var(--line)" vertical={false}/><XAxis dataKey="month" axisLine={false} tickLine={false} tick={{fontSize:12,fill:'var(--text-muted)'}}/><YAxis width={42} tickFormatter={n=>n>=1000?`${(n/1000).toFixed(0)}k`:`${n}`} axisLine={false} tickLine={false} tick={{fontSize:11,fill:'var(--text-muted)'}}/><Tooltip formatter={v=>formatMoney(Number(v))} contentStyle={{border:'1px solid var(--border)',borderRadius:12,background:'var(--surface)',color:'var(--text)'}}/><Area type="monotone" dataKey="Receitas" stroke="var(--success)" strokeWidth={2.5} fill="url(#incomeGradient)"/><Area type="monotone" dataKey="Despesas" stroke="var(--danger)" strokeDasharray="6 4" strokeWidth={2.5} fill="transparent"/></AreaChart></ResponsiveContainer>:<Empty icon={BarChart3} title="Sem dados para gráfico" body="Os lançamentos mostrarão tendências mensais." onAdd={()=>openCreate('transactions')}/>}</div></Panel><Panel title="Principais despesas" subtitle="Distribuição por categoria"><div className="category-list">{(()=>{const categories=Object.entries(tx.filter(x=>x.type!=='Receita').reduce((o,x)=>({...o,[String(x.category||'Outros')]:(o[String(x.category||'Outros')]||0)+i(x.amount)}),{} as Record<string,number>)).sort((a,b)=>b[1]-a[1]);const total=categories.reduce((s,x)=>s+x[1],0);return categories.length?categories.slice(0,5).map(([name,value])=><div key={name} className="category-row"><div className="goal-head"><strong>{name}</strong><span>{formatMoney(value)}</span></div><Progress value={value/Math.max(total,1)*100} color="blue"/></div>):<Empty icon={Wallet} title="Sem despesas registradas" body="Suas categorias aparecerão aqui automaticamente."/>})()}</div></Panel></div>
    <Panel title="Histórico de lançamentos" subtitle={`${tx.length} registros no espaço atual`} action={<div className="segmented">{['Todos','Receita','Despesa'].map(n=><button className={financialFilter===n?'selected':''} key={n} onClick={()=>setFinancialFilter(n)}>{n==='Todos'?'Todos':n+'s'}</button>)}</div>}>{tx.filter(x=>financialFilter==='Todos'||x.type===financialFilter).length?<Table rows={[...tx].filter(x=>financialFilter==='Todos'||x.type===financialFilter).sort((a,b)=>String(b.date).localeCompare(String(a.date)))} columns={[{title:'Descrição',render:x=><div className="table-primary"><IconTile variant={x.type==='Receita'?'softgreen':'softred'}>{x.type==='Receita'?<ArrowDownLeft size={17}/>:<ArrowUpRight size={17}/>}</IconTile><div><strong>{x.title}</strong><span>{x.category||'Sem categoria'}</span></div></div>},{title:'Data',render:x=>fmtDate(String(x.date||''))},{title:'Conta',render:x=>x.account||'—'},{title:'Valor',className:'amount-col',render:x=><strong className={x.type==='Receita'?'green-text':'red-text'}>{x.type==='Receita'?'+ ':'− '}{formatMoney(i(x.amount))}</strong>},{title:'',render:x=>editActions('transactions',x)}]}/>:empty('transactions',Wallet,'Nenhum lançamento encontrado')}</Panel>
   </>}
   {page==='agenda'&&<>
    <SectionHeading eyebrow="ORGANIZAÇÃO" title="Agenda e tarefas" description="Planeje seu tempo e acompanhe suas prioridades." actions={<><button className="btn light" onClick={()=>openCreate('tasks')}><Plus size={16}/> Nova tarefa</button>{commonActions('events')}</>}/>
    <div className="calendar-layout"><Panel title="Calendário" subtitle="Selecione um dia para conferir seus compromissos" action={<div className="cal-controls"><button onClick={()=>{let d=new Date(calendarMonth+'-01T12:00:00');d.setMonth(d.getMonth()-1);setCalendarMonth(`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`)}}><ChevronLeft size={17}/></button><strong>{new Date(calendarMonth+'-01T12:00:00').toLocaleDateString('pt-BR',{month:'long',year:'numeric'})}</strong><button onClick={()=>{let d=new Date(calendarMonth+'-01T12:00:00');d.setMonth(d.getMonth()+1);setCalendarMonth(`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`)}}><ChevronRight size={17}/></button></div>}>
    <div className="calendar"><div className="weekdays">{['Seg','Ter','Qua','Qui','Sex','Sáb','Dom'].map(x=><span key={x}>{x}</span>)}</div><div className="days">{(()=>{const [year,mo]=calendarMonth.split('-').map(Number);const count=new Date(year,mo,0).getDate(),offset=(new Date(year,mo-1,1).getDay()+6)%7;return [...Array.from({length:offset},(_,n)=><span key={'s'+n}/>),...Array.from({length:count},(_,k)=>{const date=`${calendarMonth}-${String(k+1).padStart(2,'0')}`;const dayEntries=event.filter(x=>x.date===date).length+task.filter(x=>x.dueDate===date).length;return <button key={date} className={cx('cal-day',selectedDate===date&&'selected',date===today()&&'today')} onClick={()=>setSelectedDate(date)}><span>{k+1}</span>{dayEntries>0&&<i/>}</button>})]})()}</div></div></Panel>
    <Panel title={fmtDate(selectedDate)} subtitle="Compromissos e tarefas desta data" action={<button className="icon-button" onClick={()=>{setForm({...initialValues('events'),date:selectedDate});setModal({kind:'events'})}} title="Adicionar evento"><Plus size={17}/></button>}><div className="day-entries">{[...event.filter(x=>x.date===selectedDate).map(x=>({...x,_kind:'events'})),...task.filter(x=>x.dueDate===selectedDate).map(x=>({...x,_kind:'tasks'}))].length?[...event.filter(x=>x.date===selectedDate).map(x=>({...x,_kind:'events'})),...task.filter(x=>x.dueDate===selectedDate).map(x=>({...x,_kind:'tasks'}))].map(x=><button key={x.id} className="day-entry" onClick={()=>openEdit(x._kind as Collection,x)}><IconTile variant="softblue">{x._kind==='events'?<CalendarDays size={16}/>:<CheckCheck size={16}/>}</IconTile><span><strong>{x.title}</strong><small>{(x as Entry).time||(x as Entry).category||'Tarefa'}</small></span><ArrowUpRight size={15}/></button>):<Empty icon={CalendarDays} title="Nenhum compromisso" body="Este dia ainda está livre." onAdd={()=>{setForm({...initialValues('events'),date:selectedDate});setModal({kind:'events'})}} cta="Adicionar evento"/>}</div></Panel></div>
    <Panel title="Minhas tarefas" subtitle={`${undone.length} pendentes · ${doneCount} concluídas`} action={<div className="segmented">{['Todos','A fazer','Em andamento','Concluído'].map(x=><button className={tab===x?'selected':''} onClick={()=>setTab(x)} key={x}>{x}</button>)}</div>}><div className="task-stack big">{task.filter(x=>tab==='Todos'||x.status===tab).length?task.filter(x=>tab==='Todos'||x.status===tab).sort((a,b)=>String(a.dueDate||'9999').localeCompare(String(b.dueDate||'9999'))).map(x=><div className="task-line" key={x.id}><button className={cx('task-box interactive',x.status==='Concluído'&&'checked')} onClick={()=>setStore(s=>({...s,collections:{...s.collections,tasks:s.collections.tasks.map(t=>t.id===x.id?{...t,status:t.status==='Concluído'?'A fazer':'Concluído'}:t)}}))} title="Alternar conclusão">{x.status==='Concluído'&&<Check size={13}/>}</button><button className={cx('task-desc',x.status==='Concluído'&&'completed')} onClick={()=>openEdit('tasks',x)}><strong>{x.title}</strong><small>{x.category||'Pessoal'} {x.dueDate?'· '+fmtDate(String(x.dueDate)):''}</small></button><Badge tone={x.priority==='Alta'?'rose':x.priority==='Média'?'amber':'muted'}>{x.priority||'Normal'}</Badge>{editActions('tasks',x)}</div>):empty('tasks',CheckCheck,'Nenhuma tarefa nesta categoria')}</div></Panel>
   </>}
   {page==='estudos'&&<Suspense fallback={<div className="module-skeleton" role="status">Preparando seu ambiente de estudos...</div>}><StudyStudio key={activeWorkspace} store={store} setStore={setStore} workspaceId={activeWorkspace}/></Suspense>}
   {page==='academia'&&<Suspense fallback={<div className="module-skeleton" role="status">Carregando Academia...</div>}><TrainingStudio key={activeWorkspace} store={store} setStore={setStore} workspaceId={activeWorkspace} legacy={workouts} onNutrition={can('alimentacao')?()=>setPage('alimentacao'):undefined} onEditLegacy={x=>openEdit('workouts',x)} onAddLegacy={()=>openCreate('workouts')}/></Suspense>}
    {page==='alimentacao'&&<Suspense fallback={<div className="module-skeleton" role="status">Carregando alimentação...</div>}><NutritionStudio store={store} setStore={setStore} workspaceId={activeWorkspace} onAcademia={can('academia')?()=>setPage('academia'):undefined}/></Suspense>}
     {page==='negocios'&&<Suspense fallback={<div className="module-skeleton" role="status"><span/><span/><span/>Carregando negócios…</div>}><BusinessERP store={store} setStore={setStore} workspaceId={activeWorkspace} workspaceTitle={workspaceTitle} clients={items('clients')} deals={items('deals')} businesses={all('businesses')} onCreateClient={()=>openCreate('clients')} onEditClient={x=>openEdit('clients',x)} onDeleteClient={x=>remove('clients',x)} onCreateBusiness={()=>openCreate('businesses')} onEditBusiness={x=>openEdit('businesses',x)} onChangeWorkspace={workspaceId=>editPrefs({workspaceId})} onCreateDeal={()=>openCreate('deals')} onEditDeal={x=>openEdit('deals',x)}/></Suspense>}
   {page==='projetos'&&<>
    <SectionHeading eyebrow="EVOLUÇÃO CONTÍNUA" title="Projetos e metas" description="Do planejamento à execução, acompanhe cada avanço." actions={<><button className="btn light" onClick={()=>openCreate('goals')}><Plus size={16}/> Nova meta</button>{commonActions('projects')}</>}/>
    <Panel title="Projetos" subtitle={`${items('projects').length} projetos neste espaço`} action={<button className="text-action" onClick={()=>openCreate('projects')}><Plus size={15}/> Novo projeto</button>}><div className="project-list">{items('projects').length?items('projects').map(x=><div className="project-row" key={x.id}><IconTile variant="softblue"><FolderKanban size={18}/></IconTile><div className="project-name"><strong>{x.title}</strong><span>{x.category||'Projeto'} {x.dueDate?'· Prazo '+fmtDate(String(x.dueDate)):''}</span></div><Badge tone={x.status==='Concluído'?'mint':x.status==='Em andamento'?'blue':'muted'}>{x.status||'Planejamento'}</Badge>{editActions('projects',x)}</div>):empty('projects',FolderKanban,'Nenhum projeto cadastrado')}</div></Panel>
    <Panel title="Metas pessoais" subtitle="Objetivos com progresso mensurável" action={<button className="text-action" onClick={()=>openCreate('goals')}><Plus size={15}/> Criar meta</button>}><div className="goals-grid">{items('goals').length?items('goals').map(x=><article className="goal-card" key={x.id}><div className="goal-card-top"><IconTile variant="softblue"><Target size={18}/></IconTile>{editActions('goals',x)}</div><h3>{x.title}</h3><strong className="goal-percent">{Math.round(i(x.current)/Math.max(1,i(x.target))*100)}%</strong><Progress value={i(x.current)/Math.max(1,i(x.target))*100} color="blue"/><div className="goal-bottom"><span>{i(x.current).toLocaleString('pt-BR')} / {i(x.target).toLocaleString('pt-BR')} {x.unit||''}</span>{x.dueDate&&<span>{fmtDate(String(x.dueDate))}</span>}</div></article>):<div className="full-empty">{empty('goals',Target,'Defina suas primeiras metas')}</div>}</div></Panel>
   </>}
   {page==='habitos'&&<Suspense fallback={<div className="module-skeleton" role="status">Carregando seus hábitos...</div>}><HabitStudio key={activeWorkspace} store={store} setStore={setStore} workspaceId={activeWorkspace}/></Suspense>}
   {page==='configuracoes'&&<>
    <SectionHeading eyebrow="PREFERÊNCIAS" title="Configurações" description="Personalize o EIXO e controle seus dados."/>
    <ModulePreferences value={store.preferences.enabledModules} onSave={enabledModules=>{editPrefs({enabledModules,onboardingVersion:1});setToast('Módulos atualizados. Seus registros foram preservados.')}}/>
    <div className="settings-layout"><Panel title="Perfil" subtitle="Informações usadas na sua experiência"><div className="settings-form"><div className="settings-identity"><Avatar name={displayName} src={account?.avatarUrl}/><strong>{displayName}</strong><button className="btn light" onClick={openAccount}>Editar perfil</button></div>{can('academia')&&<label>Meta de treinos por semana<input type="number" min="1" max="14" value={store.preferences.weeklyTrainingGoal} onChange={e=>editPrefs({weeklyTrainingGoal:Math.min(14,Math.max(1,Number(e.target.value)||1))})}/></label>}<label>Aparência<select value={store.preferences.theme} onChange={e=>editPrefs({theme:e.target.value as 'light'|'dark'})}><option value="light">Claro</option><option value="dark">Escuro</option></select></label></div></Panel>
    <Panel title="Dados e privacidade" subtitle="Dados vinculados à sua conta"><div className="privacy-line"><IconTile variant="softblue"><ShieldCheck size={19}/></IconTile><div><strong>Sincronização da conta</strong><p>Esta versão salva dados em um servidor local por conta de usuário, com sincronização após mudanças. Ainda não é hospedagem de produção com HTTPS ou infraestrutura de backups automáticos. Faça cópias de segurança regularmente.</p></div></div><div className="settings-buttons"><button className="btn light" onClick={exportData}><Download size={16}/> Exportar backup JSON</button><button className="btn light" onClick={()=>importRef.current?.click()}><FileUp size={16}/> Importar backup JSON</button><input ref={importRef} onChange={readImport} accept=".json,application/json" type="file" hidden/></div></Panel>
    <Panel title="Demonstração" subtitle="Explore todos os módulos com exemplos completos"><p className="settings-text">Preencha agenda, finanças, estudos, treinos, alimentação, projetos e hábitos. A empresa de exemplo inclui clientes, produtos, vendas, compras, estoque, contas e relatórios. Todos os módulos serão ativados no espaço Horizonte • Demonstração. Essa operação substitui seus dados atuais; exporte um backup antes de continuar.</p><button className="btn light" disabled={demoBusy} onClick={()=>void changeDemo(true)}><Sparkles size={16}/> {demoBusy?'Preparando demonstração…':'Carregar demonstração'}</button></Panel>
    <Panel title="Limpar armazenamento" subtitle="Apagar os registros deste navegador"><p className="settings-text">Essa operação exclui os dados locais do EIXO e não pode ser desfeita sem um backup.</p><button className="btn destructive" onClick={()=>{if(window.confirm('Excluir TODOS os dados locais do EIXO?')&&window.confirm('Última confirmação: apagar todos os registros?')){setStore(emptyStore());setToast('Todos os registros foram removidos.');setPage('dashboard')}}}><Trash2 size={16}/> Excluir todos os dados</button></Panel></div>
    <div className="version-info">EIXO OS · Versão 0.6.0 · Meu Dia, foco produtivo e planejamento inteligente.</div>
   </>}
   </main>
  </div>
  {toast&&<div className="toast" role="status"><Check size={17}/>{toast}<button onClick={()=>setToast('')} aria-label="Fechar"><X size={14}/></button></div>}
  {searchOpen&&<div className="overlay" onMouseDown={e=>{if(e.target===e.currentTarget)setSearchOpen(false)}}><div className="search-dialog" role="dialog" aria-modal="true" aria-label="Busca e ações rápidas">
   <div className="search-field"><Search size={21}/><input autoFocus value={search} onChange={e=>setSearch(e.target.value)} placeholder="Buscar ou acessar um módulo..." aria-label="Buscar registros e ações" onKeyDown={e=>{if(e.key==='Enter'&&paletteActions.length){e.preventDefault();runPaletteAction(paletteActions[0][1],paletteActions[0][2])}}}/><button className="search-close" type="button" onClick={()=>{setSearchOpen(false);setSearch('')}} aria-label="Fechar busca"><X size={17}/></button><kbd>ESC</kbd></div>
   <div className="search-results">
    {paletteActions.length>0&&<div className="palette-section"><p className="palette-heading">AÇÕES RÁPIDAS</p>{paletteActions.map(([label,target,kind])=><button key={label} onClick={()=>runPaletteAction(target,kind)}><IconTile variant="softblue">{kind?<Plus size={15}/>:<ArrowRight size={15}/>}</IconTile><span><strong>{label}</strong><small>{kind?'Criar registro':'Abrir módulo'}</small></span><ArrowUpRight size={16}/></button>)}</div>}
    {mainSearch&&<div className="palette-section"><p className="palette-heading">REGISTROS NESTE ESPAÇO</p>{results.length?results.map(({kind,item})=><button key={kind+item.id} onClick={()=>{setSearchOpen(false);setPage(linked[kind]||'dashboard');openEdit(kind,item);setSearch('')}}><IconTile variant="softblue"><Search size={15}/></IconTile><span><strong>{item.title}</strong><small>{config[kind].plural}</small></span><ArrowUpRight size={16}/></button>):<div className="search-tip">Nenhum registro encontrado neste espaço.</div>}</div>}
    {!mainSearch&&<div className="search-tip small-tip"><Command size={17}/> Pesquise por nome, categoria ou use os atalhos acima.</div>}
    {mainSearch&&!paletteActions.length&&!results.length&&<div className="search-tip">Tente outro termo de pesquisa.</div>}
   </div>
   <div className="dialog-footer"><span>Resultados isolados por espaço · Ctrl K</span><span>ESC para fechar</span></div>
  </div></div>}
  {modal&&<div className="overlay" onMouseDown={e=>{if(e.target===e.currentTarget)setModal(null)}}><div className="edit-dialog" role="dialog" aria-modal="true" aria-label={modal.item?'Editar registro':'Criar registro'}><header className="dialog-head"><div><span className="eyebrow">{modal.item?'EDITAR REGISTRO':'NOVO REGISTRO'}</span><h2>{modal.item?'Editar ': 'Adicionar '}{config[modal.kind].singular}</h2><p>{config[modal.kind].description}</p></div><button className="icon-button" onClick={()=>setModal(null)} aria-label="Fechar"><X size={20}/></button></header><form onSubmit={save}><div className="dialog-fields">{modal.kind==='businesses'&&<ImageUpload name={form.title||'Empresa'} imageId={form.logoId} workspaceId={modal.item?.id||activeWorkspace} onChange={id=>setForm(f=>({...f,logoId:id}))} onBusy={setBusinessUpload} onError={setToast}/>} {config[modal.kind].fields.map(field=><label key={field.key} className={field.kind==='textarea'?'wide':''}><span>{field.label}{field.required&&<em> *</em>}</span>{field.kind==='select'?<select value={form[field.key]||''} onChange={e=>setForm(v=>({...v,[field.key]:e.target.value}))} required={field.required}><option value="">Selecione...</option>{field.options?.map(o=><option key={o} value={o}>{o}</option>)}</select>:field.kind==='textarea'?<textarea rows={3} value={form[field.key]||''} onChange={e=>setForm(v=>({...v,[field.key]:e.target.value}))} placeholder="Informações adicionais (opcional)"/>:<input required={field.required} type={field.key==='email'?'email':['phone','whatsapp'].includes(field.key)?'tel':field.kind||'text'} inputMode={field.kind==='number'?'decimal':undefined} step={field.kind==='number'?'any':undefined} min={field.kind==='number'?'0':undefined} value={form[field.key]||''} placeholder={field.placeholder||''} onChange={e=>setForm(v=>({...v,[field.key]:e.target.value}))}/>}</label>)}</div><footer className="form-footer"><button type="button" className="btn light" onClick={()=>setModal(null)}>Cancelar</button><button type="submit" disabled={businessUpload} className="btn primary"><Check size={16}/>{modal.item?'Salvar alterações':'Adicionar registro'}</button></footer></form></div></div>}
 </div>
}

